\begin{theorem}
There are infinitely many primes.
\end{theorem}

\begin{proof}
Suppose $p_1, p_2, \ldots, p_n$ are all the primes. Let
\begin{equation}
  N = p_1 p_2 \cdots p_n + 1.
\end{equation}
Some prime $p$ divides $N$, so $p = p_i$ for some $i$. But then
$p \mid N$ and $p \mid N - 1$, hence $p \mid 1$, a contradiction.
\end{proof}
